<script setup lang="ts">
import {onMounted,ref} from 'vue';import {useCommerce} from '../lib/commerce';import {t} from '../i18n';import '../commerce.css';
const {read,api,busy,error,notice}=useCommerce(),settings=ref({sales:false,redemption:true,tickets:true,currency:'CNY',payment_provider:'manual',payment_webhook_url:'',mail_provider:'none',mail_from:'',mail_webhook_url:''}),password=ref('');
onMounted(async()=>{const v=await read<typeof settings.value>('/settings');if(v)settings.value=v});
async function save(){busy.value=true;error.value='';try{await api('/settings','POST',{settings:settings.value,password:password.value});notice.value=t('账户服务设置已保存')}catch(e){error.value=t((e as Error).message)}finally{password.value='';busy.value=false}}
</script>
<template><form class="commerce-page commerce-card" @submit.prevent="save"><h2>{{t('余额、兑换码与工单')}}</h2><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><label class="inline-check"><input v-model="settings.sales" type="checkbox"/>{{t('保留旧版销售开关（兼容）')}}</label><small class="commerce-muted">{{t('实际是否可购买由“套餐上架”页面中的上架状态决定。')}}</small><label class="inline-check"><input v-model="settings.redemption" type="checkbox"/>{{t('开放兑换码充值')}}</label><label class="inline-check"><input v-model="settings.tickets" type="checkbox"/>{{t('允许成员提交工单')}}</label><section class="commerce-integration"><h3>{{t('第三方接入准备')}}</h3><label>{{t('支付方式')}}<select v-model="settings.payment_provider"><option value="manual">{{t('站内余额 / 手动')}}</option><option value="webhook">{{t('Webhook 预留')}}</option></select></label><label>{{t('支付回调地址')}}<input v-model="settings.payment_webhook_url" type="url" placeholder="https://example.com/payment/webhook"/></label><label>{{t('邮件服务')}}<select v-model="settings.mail_provider"><option value="none">{{t('暂不接入')}}</option><option value="webhook">{{t('Webhook 预留')}}</option></select></label><label>{{t('发件人地址')}}<input v-model="settings.mail_from" type="email" placeholder="noreply@example.com"/></label><label>{{t('邮件回调地址')}}<input v-model="settings.mail_webhook_url" type="url" placeholder="https://example.com/mail/webhook"/></label><small class="commerce-muted">{{t('当前只保存接入配置，不会主动调用外部支付或邮件服务。')}}</small></section><label>{{t('管理员当前密码')}}<input v-model="password" type="password" autocomplete="current-password" required/></label><button class="primary" :disabled="busy">{{t('保存账户服务设置')}}</button></form></template>
